  ctx.save(); ctx.globalCompositeOperation = 'lighter'; for (let i = 0; i < 5; i++) { ctx.globalAlpha = .07 + .03 * Math.sin(t + i); poly(ctx, [vx - 100 + i * 50, vy - 340, vx - 60 + i * 50, vy - 340, vx - 420 + i * 220, 1700, vx - 560 + i * 220, 1700]); ctx.fillStyle = '#FFE2A8'; ctx.fill(); } ctx.restore();
  hall(ctx, vx, vy, { col: '#E8DCC4', floor: '#B89A74', n: 6, spread: 560, colH: 1050, floorY: 1560 });
  // altar
