// S6 — mina / minerador liberto 25.6–33.1
function S_mine(ctx, t, T) {
  ctx.save(); cam(ctx, 1.04 + ease(t / 7.5) * .06, W / 2, 1400);
  const vx = W / 2, vy = 780;
  ctx.fillStyle = '#120B08'; ctx.fillRect(0, 0, W, H);
  // tunnel frames receding
  const speed = t < 2.1 ? 1.6 : .25, sh = (T * speed) % 1;
  for (let i = 9; i >= 0; i--) {
    const zz = i + 1 - sh, k = 1 / (zz * .42 + .2); if (k > 4) continue;
    const hw = 640 * k, top = vy - 520 * k, bot = vy + 760 * k, dark = clamp(1 - k * .9);
    ctx.fillStyle = mix('#5A3A28', '#120B08', dark); poly(ctx, [vx - hw, bot, vx - hw * 1.18, top, vx + hw * 1.18, top, vx + hw, bot]); ctx.globalAlpha = .35; ctx.fill(); ctx.globalAlpha = 1;
    const beam = 50 * k, wood = mix('#8A5A34', '#140C08', dark);
    ctx.fillStyle = wood; ctx.fillRect(vx - hw - beam / 2, top, beam, bot - top); ctx.fillRect(vx + hw - beam / 2, top, beam, bot - top); ctx.fillRect(vx - hw - beam, top - beam * .5, hw * 2 + beam * 2, beam);
    if (i % 2 === 0) { const tx = vx - hw + beam * 1.2, ty = top + (bot - top) * .35; fire(ctx, tx, ty, 18 * k, 34 * k, T + i, i); glow(ctx, tx, ty - 10 * k, 260 * k, '#FF9A3C', .5 * (1 - dark)); }
  }
  // rails
  ctx.strokeStyle = '#6E6A6A'; ctx.lineWidth = 8; [-1, 1].forEach(s => { ctx.beginPath(); ctx.moveTo(vx + s * 20, vy + 20); ctx.lineTo(vx + s * 300, H + 100); ctx.stroke(); });
  // ore carts rushing (first part)
  if (t < 2.4) for (let c = 0; c < 3; c++) { const p = ((T * 1.2 + c / 3) % 1); const k = .3 + p * p * 2.8; const cy = vy + 60 + p * p * 900; ctx.save(); ctx.translate(vx, cy); ctx.scale(k, k); rrect(ctx, -110, -80, 220, 90, 10); ctx.fillStyle = '#5A3E2E'; ctx.fill(); for (let q = 0; q < 6; q++) { circle(ctx, -80 + q * 32, -84 - (q % 2) * 14, 26); ctx.fillStyle = q % 2 ? '#5C5A62' : '#7A7880'; ctx.fill(); } ctx.restore(); }
  // ×4 counter
  const cp = prog(t, .7, 1.1) * (1 - prog(t, 2.0, 2.3)); if (cp > 0) { ctx.save(); ctx.globalAlpha = cp; ctx.translate(W / 2, 430); ctx.scale(lerp(1.5, 1, easeOut(cp)), lerp(1.5, 1, easeOut(cp))); ctx.font = '230px Anton'; ctx.textAlign = 'center'; ctx.textBaseline = 'middle'; ctx.lineWidth = 16; ctx.strokeStyle = '#2A1408'; ctx.strokeText('×4', 0, 0); ctx.fillStyle = '#F5B83D'; ctx.fillText('×4', 0, 0); ctx.font = '50px Anton'; ctx.fillStyle = '#fff'; ctx.strokeText('FERRO', 0, 150); ctx.fillText('FERRO', 0, 150); ctx.restore(); }
  // miner
  const mp = easeOut(prog(t, 1.9, 2.5));
  if (mp > 0) {
    const free = prog(t, 4.2, 4.7), op = prog(t, 5.2, 5.7);
    if (free > 0) glow(ctx, W / 2, 900, 700 * free, '#FFE2A0', .55 * free);
    ctx.save(); ctx.globalAlpha = mp;
    person(ctx, W / 2, 1410 + (1 - mp) * 80, 6.0, { t, tunic: op > .5 ? '#3F6E9E' : '#7A6450', skin: SKIN[1], hair: '#1E1410', chains: free < 1 || true, chainLink: free < .99, chainBreak: free, apron: op > .5 ? '#5A3A22' : null, pileus: op, armL: free > 0 ? [lerp(.3, 2.5, easeBack(free)), lerp(.4, .3, free)] : [.3, .4], armR: free > 0 ? [lerp(-.3, -2.5, easeBack(free)), lerp(-.4, -.3, free)] : [-.3, -.4], lookY: free > 0 ? -1 : 1, brow: free > 0 ? 2 : -1, smile: free > 0 ? 1.4 : -.6, mouth: free > .3 && op < .2 ? .7 : 0, seed: 3 });
    ctx.restore();
    if (op > 0) for (let i = 0; i < 6; i++) { const p = clamp((t - 5.4 - i * .12) / .9); if (p <= 0) continue; coin(ctx, W / 2 + (i - 2.5) * 70 * (1 - p * .4), lerp(300, 860, easeIn(p)) + Math.sin(i) * 20, 30, T * 8 + i); }
    // broken chain bits flying
    if (free > 0 && free < 1) for (let i = 0; i < 6; i++) { const a = i / 6 * TAU; ellipse(ctx, W / 2 + Math.cos(a) * free * 260, 950 + Math.sin(a) * free * 200, 12, 8, a); ctx.strokeStyle = `rgba(160,165,175,${1 - free})`; ctx.lineWidth = 5; ctx.stroke(); }
  }
  ctx.restore();
  vignette(ctx, .55);
}

