  layer(ctx, .8, camX, 0, () => { ground(ctx, 1290, '#7A5E4E', '#3A2A22'); for (let i = 0; i < 7; i++) insula(ctx, i * 330 - 100, 1300, 290, 420 + hash(i * 7) * 120, mix('#E2A777', '#7A4A4A', .25), { lit: .7, door: true }); });
