  for (let i = 0; i < 9; i++) { const sp = 120 + hash(i) * 60; const x = ((i * 230 + t * sp + 2000) % 2100) - 400; const sc = 3.2 + hash(i * 5) * 1.1, y = 1290 + sc * 26; person(ctx, x, y, sc, { t: T, walk: T * 7 + i, tunic: cols[i % 6], skin: SKIN[i % 3], hair: ['#2B1B14', '#6A3E1E', '#1A1410'][i % 3], pileus: i % 2 ? 1 : 0, apron: i % 3 === 0 ? '#5A3A22' : null, lookX: 1, seed: i, armL: [Math.sin(T * 7 + i) * .4, .2], armR: [-Math.sin(T * 7 + i) * .4, -.2], smile: .9, hold: i % 3 === 1 ? (c, h) => coin(c, h[1][0], h[1][1], 5, T * 5) : null }); }
  ctx.restore();
