  if (drop > 0) { ctx.save(); ctx.translate(330, 1380); ctx.scale(.75, .75); ctx.rotate(1.3 * drop); ctx.globalAlpha = 1; rrect(ctx, -70, -150 + drop * 120, 140, 230, 30); ctx.fillStyle = '#8A2E25'; ctx.fill(); ctx.strokeStyle = '#D9A93F'; ctx.lineWidth = 8; ctx.stroke(); circle(ctx, 0, -35 + drop * 120, 26); ctx.fillStyle = '#D9A93F'; ctx.fill(); ctx.restore(); }
  plaque(ctx, '200 d.C.', prog(t, .45, .85), { y: 300 });
