// ===== scenes3.js =====
// futuristic neo-roman skyline helper
function neoSkyline(ctx, yb, t, o = {}) {
  for (let i = 0; i < 9; i++) {
    const x = i * 135 - 40 + hash(i) * 30, h = (o.hs || 1) * (300 + hash(i * 3) * 340), w = 100 + hash(i * 5) * 60;
    ctx.fillStyle = lg(ctx, x, 0, x + w, 0, [[0, '#2A3A5E'], [.5, '#3E5A86'], [1, '#1E2A48']]); ctx.fillRect(x, yb - h, w, h);
    // glass windows
    for (let r = 0; r < h / 40 - 1; r++) for (let c = 0; c < 3; c++) if (hash(i * 31 + r * 7 + c) < .55) { ctx.fillStyle = 'rgba(255,214,140,.75)'; ctx.fillRect(x + 14 + c * (w - 28) / 3, yb - h + 30 + r * 40, (w - 28) / 3 - 8, 16); }
    // classical pediment crown
    poly(ctx, [x - 10, yb - h, x + w + 10, yb - h, x + w / 2, yb - h - 46]); ctx.fillStyle = '#EDE3CF'; ctx.fill();
    ctx.fillStyle = '#EDE3CF'; for (let c = 0; c < 4; c++) ctx.fillRect(x + 6 + c * (w - 18) / 3, yb - h, 8, 40);
    if (hash(i * 9) < .4) { ctx.strokeStyle = '#7CF3FF'; ctx.lineWidth = 3; ctx.shadowColor = '#7CF3FF'; ctx.shadowBlur = 16; ctx.strokeRect(x, yb - h, w, h); ctx.shadowBlur = 0; }
  }
}

