  circle(ctx, 780, 420, 90); ctx.fillStyle = '#F4EBCB'; ctx.fill(); glow(ctx, 780, 420, 300, '#BFD3FF', .35);
  const fp = prog(t, 2.9, 3.6);
  if (fp > 0) { ctx.save(); ctx.globalAlpha = fp * .85; ctx.translate(0, 0); rocket(ctx, 260, 760, .7, T, { flame: true }); automaton(ctx, 820, 900, .8, T); ctx.restore(); glow(ctx, 260, 640, 260, '#4FB6FF', .35 * fp); glow(ctx, 820, 700, 260, '#FF6B57', .3 * fp); }
