  const road = (dir, col) => { ctx.beginPath(); ctx.moveTo(W / 2 - 160, H + 50); ctx.quadraticCurveTo(W / 2 - 20 + dir * 40, 1520, W / 2 + dir * 330, 1300); ctx.lineTo(W / 2 + dir * 300 + 40 * (dir > 0 ? 1 : 0) - (dir < 0 ? 40 : 0) + dir * 10, 1300); ctx.quadraticCurveTo(W / 2 + 40 + dir * 60, 1540, W / 2 + 160, H + 50); ctx.closePath(); ctx.fillStyle = col; ctx.fill(); };
