const EG = { areia: '#E3C28A', lapis: '#2F5DA8', ouro: '#D4A017', turquesa: '#3FB8AF', linho: '#F2E8D0', terracota: '#B5523B', cobre: '#B87333', faisca: '#7CF3FF', calcario: '#D9C49A' };

